/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// Common class for customer and vendor external data
/// </summary>
public class METTAMRebateJournalTransExternalData extends TAMRebateJournalTrans
{
    protected METRebateScanSupplierTable externalSalesData;

}

Method.Source:
/// <summary>
/// Set journal transaction, simplified from TAMRebateJournalTransPurchOrder and TAMRebateJournalTransSalesOrder
/// </summary>
/// <param name = "_journal"><t>METRebateScanSupplierTable</t></param>
/// <param name = "_transaction"><t>METRebateScanSupplierTable</t></param>
public void setJournalTransaction(Common _journal, Common _transaction)
{
    externalSalesData = _transaction as METRebateScanSupplierTable;

    taxItemGroup = externalSalesData.ItemGSTGroup;

    super(_journal, _transaction);
}

/// <summary>
/// Init rebate trans from journal
/// </summary>
/// <param name = "_rebateTrans"><t>TAMRebateTrans</t></param>
public void inititalizeRebateTransactionFromJournal(TAMRebateTrans _rebateTrans)
{
    super(_rebateTrans);

    _rebateTrans.metInitFromExternalSalesData(externalSalesData);

    _rebateTrans.CashDiscCode = "";

    // Rebate will not be configured with inventory dimension
    InventDim inventDimAllBlank;
    changecompany (externalSalesData.DataAreaId)
    {
        inventDimAllBlank = InventDim::findOrCreateBlank();
    }
    _rebateTrans.InventDimId = inventDimAllBlank.inventDimId;
}

/// <summary>
/// Common method
/// </summary>
/// <returns>TAMRebateRefDate</returns>
public TAMRebateRefDate rebateRefDate()
{
    return DateTimeUtil::date(externalSalesData.TransactionDate);
}

/// <summary>
/// Common method
/// </summary>
/// <returns>TAMRebateRefAmount</returns>
protected TAMRebateRefAmount calcJournalTransAmountExclTax()
{
    return externalSalesData.SalesValue;
}

/// <summary>
/// Common method
/// </summary>
/// <returns>TAMRebateRefAmount</returns>
protected TAMRebateRefAmount calcJournalTransGrossAmountExclTax()
{

    return externalSalesData.SalesValue;
}

/// <summary>
/// Bug 308508
/// For Rebate management deal customer or vendor, standard call looks for InventTransId field value with call for getInventTransId(),
/// which we dont have or hold under custom table - METRebateSupplierScanTable. So override to always return false, that helps to skip further call under isMappedCreditNote().
/// Bug 308508
/// </summary>
/// <returns>ALways false since external sales data does not have InventTransId</returns>
protected boolean isTransactionHasInventTransId()
{
    return false;
}

/// <summary>
/// Bug 308508
/// For Rebate management deal customer or vendor, standard call looks for InventTransId field value with call for getInventTransId(),
/// which we dont have or hold under custom table - METRebateSupplierScanTable. So override to always return false, that helps to skip further call under isMappedCreditNote().
/// Bug 308508
/// </summary>
/// <returns>Return '' for transaction is from External sales data, in other cases the base/super call will ake care , providing InventTransId </returns>
protected InventTransId getInventTransId()
{
    InventTransId inventTransId;
    if (transaction.TableId == tableNum(METRebateScanSupplierTable))
    {   
        inventTransId = '';
    }
    else
    {
        inventTransId = super();
    }
    return inventTransId;
}
